/* ==========================================================
   INVOICE APP — FRONTEND LOGIC
   Talks to a Google Apps Script Web App (see AppsScript_Code.gs)
   ========================================================== */

// PASTE YOUR APPS SCRIPT WEB APP URL HERE (ends in /exec)
const API_URL = "https://script.google.com/macros/s/AKfycbw5CBURcpquWehNIZwe0E8GrsTBO3AXRnG4U8pxxv5ki0_12JkXpS1-fl_2nDxAjLGC/exec";


// Fixed business info — hardcoded here, no longer read from the Settings sheet
const BUSINESS_INFO = {
  BusinessName: "Rajesh S Chandan",
  Address: "Shop No.1 Baba Homes CHS Plot No. 307 Sector 21 Seawood Nerul 400706",
  Phone: "9820233238",
  Email: "rchandan3@gmail.com",
  State: "27-Maharashtra"
};

// Embedded signature image (base64) — captured once, no external hosting needed
const SIGNATURE_IMAGE_B64 = "data:image/png;base64,";

let STATE = {
  settings: BUSINESS_INFO,
  clients: [],
  items: [],
  nextInvoiceNo: 1001
};

const el = (id) => document.getElementById(id);

/* ---------------------- INIT ---------------------- */
document.addEventListener("DOMContentLoaded", async () => {
  el("invoiceDate").valueAsDate = new Date();
  addItemRow(); // start with one blank item row

  // Business info is hardcoded and doesn't depend on the network — render it
  // immediately so the header always shows even if the API call below fails.
  STATE.settings = BUSINESS_INFO;
  renderPreview();

  attachStaticListeners();
  await loadBootstrapData();
});

async function loadBootstrapData() {
  setStatus("connecting");
  try {
    const res = await fetch(`${API_URL}?action=bootstrap`);
    if (!res.ok) throw new Error("Network error");
    const data = await res.json();
    if (data.error) throw new Error(data.error);

    STATE.settings = BUSINESS_INFO;
    STATE.clients = data.clients || [];
    STATE.items = data.items || [];
    STATE.nextInvoiceNo = data.nextInvoiceNo || 1001;

    el("invoiceNo").value = STATE.nextInvoiceNo;
    populateClientDatalist();
    populateItemDatalist();
    renderPreview();
    setStatus("online");
  } catch (err) {
    console.error(err);
    setStatus("error");
    showMessage("Could not connect to Google Sheets (client/item lookup won't autofill), but business info and invoice generation still work. Check API_URL in app.js and that the Apps Script is deployed.", "error");
  }
}

function setStatus(state) {
  const pill = el("statusPill");
  pill.classList.remove("status-online", "status-offline", "status-error");
  if (state === "online") {
    pill.textContent = "Connected";
    pill.classList.add("status-online");
  } else if (state === "error") {
    pill.textContent = "Connection failed";
    pill.classList.add("status-error");
  } else {
    pill.textContent = "Connecting…";
    pill.classList.add("status-offline");
  }
}

/* ---------------------- STATIC LISTENERS ---------------------- */
function attachStaticListeners() {
  el("addItemBtn").addEventListener("click", () => addItemRow());
  el("generateBtn").addEventListener("click", onGenerateInvoice);

  el("clientInput").addEventListener("input", onClientChange);
  ["clientInput", "invoiceNo", "invoiceDate", "clientAddress", "clientPhone", "clientState", "receivedInput"]
    .forEach(id => el(id).addEventListener("input", renderPreview));
}

/* ---------------------- CLIENT AUTOFILL ---------------------- */
function populateClientDatalist() {
  const list = el("clientList");
  list.innerHTML = "";
  STATE.clients.forEach(c => {
    const opt = document.createElement("option");
    opt.value = c.clientName;
    list.appendChild(opt);
  });
}

function onClientChange() {
  const name = el("clientInput").value.trim();
  const match = STATE.clients.find(c => c.clientName.toLowerCase() === name.toLowerCase());
  if (match) {
    el("clientAddress").value = match.address || "";
    el("clientPhone").value = match.phone || "";
    el("clientState").value = match.state || "";
  }
  renderPreview();
}

/* ---------------------- ITEM AUTOFILL ---------------------- */
function populateItemDatalist() {
  const list = el("itemNameList");
  list.innerHTML = "";
  STATE.items.forEach(it => {
    const opt = document.createElement("option");
    opt.value = it.itemName;
    list.appendChild(opt);
  });
}

function addItemRow(prefill) {
  const template = el("itemRowTemplate");
  const clone = template.content.cloneNode(true);
  const row = clone.querySelector(".item-row");

  const nameInput = row.querySelector(".item-name-input");
  const hsnInput = row.querySelector(".item-hsn-input");
  const qtyInput = row.querySelector(".item-qty-input");
  const priceInput = row.querySelector(".item-price-input");
  const removeBtn = row.querySelector(".btn-remove");

  if (prefill) {
    nameInput.value = prefill.itemName || "";
    hsnInput.value = prefill.hsnSac || "";
    qtyInput.value = prefill.quantity || 1;
    priceInput.value = prefill.pricePerUnit || "";
  }

  nameInput.addEventListener("input", () => {
    const match = STATE.items.find(it => it.itemName.toLowerCase() === nameInput.value.trim().toLowerCase());
    if (match) {
      hsnInput.value = match.hsnSac || "";
      if (!priceInput.value) priceInput.value = match.defaultPrice || "";
    }
    renderPreview();
  });
  [hsnInput, qtyInput, priceInput].forEach(input => input.addEventListener("input", renderPreview));

  removeBtn.addEventListener("click", () => {
    row.remove();
    renderPreview();
  });

  el("itemsList").appendChild(row);
}

/* ---------------------- READ FORM STATE ---------------------- */
function getFormItems() {
  const rows = document.querySelectorAll(".item-row");
  const items = [];
  rows.forEach(row => {
    const itemName = row.querySelector(".item-name-input").value.trim();
    const hsnSac = row.querySelector(".item-hsn-input").value.trim();
    const quantity = parseFloat(row.querySelector(".item-qty-input").value) || 0;
    const pricePerUnit = parseFloat(row.querySelector(".item-price-input").value) || 0;
    if (!itemName && quantity === 0 && pricePerUnit === 0) return; // skip fully empty rows
    items.push({ itemName, hsnSac, quantity, pricePerUnit, amount: quantity * pricePerUnit });
  });
  return items;
}

/* ---------------------- LIVE PREVIEW ---------------------- */
function renderPreview() {
  const settings = STATE.settings;
  el("bizName").textContent = settings.BusinessName || "—";
  el("bizAddress").textContent = settings.Address || "";
  el("bizPhone").textContent = settings.Phone ? `Phone no.: ${settings.Phone}` : "";
  el("bizEmail").textContent = settings.Email ? `Email: ${settings.Email}` : "";
  el("bizState").textContent = settings.State ? `State: ${settings.State}` : "";
  const sigImg = el("sigImage");
  if (sigImg && !sigImg.src.startsWith("data:")) {
    sigImg.src = SIGNATURE_IMAGE_B64;
  }

  el("metaClientName").textContent = el("clientInput").value.trim() || "—";
  el("metaInvoiceNo").textContent = el("invoiceNo").value || "—";
  el("metaInvoiceDate").textContent = formatDateDisplay(el("invoiceDate").value);

  const items = getFormItems();
  const tbody = el("invTableBody");
  tbody.innerHTML = "";
  let totalQty = 0;
  let subTotal = 0;

  items.forEach((item, idx) => {
    totalQty += item.quantity;
    subTotal += item.amount;
    const tr = document.createElement("tr");
    tr.innerHTML = `
      <td>${idx + 1}</td>
      <td>${escapeHtml(item.itemName)}${item.hsnSac ? `<div class="item-hsn-sub">${escapeHtml(item.hsnSac)}</div>` : ""}</td>
      <td>${escapeHtml(item.hsnSac)}</td>
      <td class="col-qty">${item.quantity}</td>
      <td class="col-price">₹ ${formatMoney(item.pricePerUnit)}</td>
      <td class="col-amount">₹ ${formatMoney(item.amount)}</td>
    `;
    tbody.appendChild(tr);
  });

  el("totalQty").textContent = totalQty;
  el("totalAmount").textContent = `₹ ${formatMoney(subTotal)}`;

  const received = parseFloat(el("receivedInput").value) || 0;
  const balance = subTotal - received;

  el("sumSubTotal").textContent = `₹ ${formatMoney(subTotal)}`;
  el("sumTotal").textContent = `₹ ${formatMoney(subTotal)}`;
  el("sumReceived").textContent = `₹ ${formatMoney(received)}`;
  el("sumBalance").textContent = `₹ ${formatMoney(balance)}`;

  el("previewSubTotal").textContent = `₹ ${formatMoney(subTotal)}`;
  el("previewTotal").textContent = `₹ ${formatMoney(subTotal)}`;
  el("previewReceived").textContent = `₹ ${formatMoney(received)}`;
  el("previewBalance").textContent = `₹ ${formatMoney(balance)}`;

  el("amountWords").textContent = subTotal > 0 ? numberToWordsRupees(subTotal) : "—";
}

/* ---------------------- GENERATE / SAVE ---------------------- */
async function onGenerateInvoice() {
  const clientName = el("clientInput").value.trim();
  const items = getFormItems();

  if (!clientName) {
    showMessage("Please enter a client name.", "error");
    el("clientInput").focus();
    return;
  }
  if (items.length === 0) {
    showMessage("Please add at least one item.", "error");
    return;
  }

  const invoiceNo = el("invoiceNo").value.trim();
  const invoiceDate = el("invoiceDate").value;
  const subTotal = items.reduce((sum, it) => sum + it.amount, 0);
  const received = parseFloat(el("receivedInput").value) || 0;

  const invoice = {
    invoiceNo,
    invoiceDate: formatDateDisplay(invoiceDate),
    clientName,
    clientAddress: el("clientAddress").value.trim(),
    clientPhone: el("clientPhone").value.trim(),
    clientEmail: "",
    clientState: el("clientState").value.trim(),
    subTotal,
    received,
    amountInWords: numberToWordsRupees(subTotal)
  };

  const generateBtn = el("generateBtn");
  generateBtn.disabled = true;
  generateBtn.textContent = "Saving…";
  showMessage("Saving to Google Sheets…", "");

  try {
    const res = await fetch(API_URL, {
      method: "POST",
      body: JSON.stringify({ action: "saveInvoice", payload: { invoice, items } })
    });
    const data = await res.json();
    if (data.error) throw new Error(data.error);

    showMessage("Saved! Preparing PDF…", "success");

    // Update local cache so next invoice for same client/items autofills without refetch
    upsertLocalClient(invoice);
    items.forEach(it => upsertLocalItem(it));
    populateClientDatalist();
    populateItemDatalist();

    await exportToPdf(clientName, invoiceNo);

    showMessage(`Invoice #${invoiceNo} saved and downloaded.`, "success");

    // Prepare for next invoice
    const nextNo = (parseInt(invoiceNo, 10) || STATE.nextInvoiceNo) + 1;
    STATE.nextInvoiceNo = nextNo;
    resetFormForNextInvoice(nextNo);

  } catch (err) {
    console.error(err);
    showMessage("Could not save invoice: " + err.message, "error");
  } finally {
    generateBtn.disabled = false;
    generateBtn.textContent = "Generate & Save Invoice";
  }
}

function upsertLocalClient(invoice) {
  const idx = STATE.clients.findIndex(c => c.clientName.toLowerCase() === invoice.clientName.toLowerCase());
  const record = {
    clientId: idx >= 0 ? STATE.clients[idx].clientId : "local",
    clientName: invoice.clientName,
    address: invoice.clientAddress,
    phone: invoice.clientPhone,
    email: invoice.clientEmail,
    state: invoice.clientState
  };
  if (idx >= 0) STATE.clients[idx] = record;
  else STATE.clients.push(record);
}

function upsertLocalItem(item) {
  const idx = STATE.items.findIndex(i => i.itemName.toLowerCase() === item.itemName.toLowerCase());
  const record = { itemId: idx >= 0 ? STATE.items[idx].itemId : "local", itemName: item.itemName, hsnSac: item.hsnSac, defaultPrice: item.pricePerUnit };
  if (idx >= 0) STATE.items[idx] = record;
  else STATE.items.push(record);
}

function resetFormForNextInvoice(nextNo) {
  el("clientInput").value = "";
  el("clientAddress").value = "";
  el("clientPhone").value = "";
  el("clientState").value = "";
  el("receivedInput").value = "";
  el("invoiceNo").value = nextNo;
  el("invoiceDate").valueAsDate = new Date();
  el("itemsList").innerHTML = "";
  addItemRow();
  renderPreview();
}

/* ---------------------- PDF EXPORT ---------------------- */
async function exportToPdf(clientName, invoiceNo) {
  const sheet = el("invoiceSheet");
  const safeClientName = clientName.replace(/[^a-z0-9]+/gi, "_").replace(/^_+|_+$/g, "");
  const filename = `${safeClientName}_${invoiceNo}.pdf`;

  // Force a fixed desktop-style width for the export, regardless of the
  // device's actual screen size — prevents cramped/wrapped layout on mobile.
  const EXPORT_WIDTH_PX = 800;
  const originalWidth = sheet.style.width;
  const originalMaxWidth = sheet.style.maxWidth;
  const originalPosition = sheet.style.position;
  const originalLeft = sheet.style.left;
  const originalMargin = sheet.style.margin;

  // Take the sheet out of the parent's flex-centering (.preview-scroll uses
  // justify-content:center) and pin it to a known x=0 offset. Without this,
  // html2canvas's `windowWidth` override disagrees with the sheet's actual
  // centered position in the real (wider) viewport, shifting the capture
  // sideways in the final image/PDF.
  sheet.style.width = EXPORT_WIDTH_PX + "px";
  sheet.style.maxWidth = EXPORT_WIDTH_PX + "px";
  sheet.style.position = "relative";
  sheet.style.left = "0";
  sheet.style.margin = "0";

  // Let the browser apply the width/position change before capturing
  await new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve)));

  let canvas;
  try {
    canvas = await html2canvas(sheet, {
      scale: 2,
      backgroundColor: "#ffffff",
      windowWidth: EXPORT_WIDTH_PX,
      width: EXPORT_WIDTH_PX,
      x: 0,
      y: 0,
      scrollX: 0,
      scrollY: 0
    });
  } finally {
    // Restore the on-screen responsive layout
    sheet.style.width = originalWidth;
    sheet.style.maxWidth = originalMaxWidth;
    sheet.style.position = originalPosition;
    sheet.style.left = originalLeft;
    sheet.style.margin = originalMargin;
  }

  const imgData = canvas.toDataURL("image/png");

  const { jsPDF } = window.jspdf;
  const pdf = new jsPDF({ orientation: "portrait", unit: "pt", format: "a4" });
  const pageWidth = pdf.internal.pageSize.getWidth();
  const pageHeight = pdf.internal.pageSize.getHeight();

  const imgWidth = pageWidth;
  const imgHeight = (canvas.height * imgWidth) / canvas.width;

  let heightLeft = imgHeight;
  let position = 0;

  pdf.addImage(imgData, "PNG", 0, position, imgWidth, imgHeight);
  heightLeft -= pageHeight;

  while (heightLeft > 0) {
    position = heightLeft - imgHeight;
    pdf.addPage();
    pdf.addImage(imgData, "PNG", 0, position, imgWidth, imgHeight);
    heightLeft -= pageHeight;
  }

  const blob = pdf.output("blob");

  // Prefer the native "Save As" file picker when the browser supports it (desktop Chrome/Edge)
  if (window.showSaveFilePicker) {
    try {
      const handle = await window.showSaveFilePicker({
        suggestedName: filename,
        types: [{ description: "PDF file", accept: { "application/pdf": [".pdf"] } }]
      });
      const writable = await handle.createWritable();
      await writable.write(blob);
      await writable.close();
      return;
    } catch (err) {
      if (err.name === "AbortError") return; // user cancelled save dialog
      console.warn("Save picker failed, falling back to direct download.", err);
    }
  }

  // Fallback (mobile / unsupported browsers): standard download with filename pre-filled
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

/* ---------------------- HELPERS ---------------------- */
function formatMoney(n) {
  return (n || 0).toLocaleString("en-IN", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function formatDateDisplay(isoDate) {
  if (!isoDate) return "";
  const [y, m, d] = isoDate.split("-");
  return `${d}-${m}-${y}`;
}

function escapeHtml(str) {
  const div = document.createElement("div");
  div.textContent = str || "";
  return div.innerHTML;
}

function showMessage(text, type) {
  const msg = el("formMessage");
  msg.textContent = text;
  msg.className = "form-message" + (type ? " " + type : "");
}

/* ---------------------- NUMBER TO WORDS (Indian system, Rupees) ---------------------- */
function numberToWordsRupees(amount) {
  const rupees = Math.floor(amount);
  const paise = Math.round((amount - rupees) * 100);

  const words = numberToWordsIndian(rupees);
  let result = `${words} Rupees`;
  if (paise > 0) {
    result += ` and ${numberToWordsIndian(paise)} Paise`;
  }
  return result + " only";
}

function numberToWordsIndian(num) {
  if (num === 0) return "Zero";

  const ones = ["", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine",
    "Ten", "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen"];
  const tens = ["", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"];

  function twoDigits(n) {
    if (n < 20) return ones[n];
    return tens[Math.floor(n / 10)] + (n % 10 ? " " + ones[n % 10] : "");
  }
  function threeDigits(n) {
    if (n < 100) return twoDigits(n);
    return ones[Math.floor(n / 100)] + " Hundred" + (n % 100 ? " " + twoDigits(n % 100) : "");
  }

  let parts = [];
  let crore = Math.floor(num / 10000000); num %= 10000000;
  let lakh = Math.floor(num / 100000); num %= 100000;
  let thousand = Math.floor(num / 1000); num %= 1000;
  let hundred = num;

  if (crore) parts.push(threeDigits(crore) + " Crore");
  if (lakh) parts.push(threeDigits(lakh) + " Lakh");
  if (thousand) parts.push(threeDigits(thousand) + " Thousand");
  if (hundred) parts.push(threeDigits(hundred));

  return parts.join(" ");
}